class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def is_complete_binary_tree(root):
    if not root:
        return True
    queue = [root]
    flag = True
    while queue:
        node = queue.pop(0)
        if node.left:
            if not flag:
                return False
            queue.append(node.left)
        else:
            flag = False
        if node.right:
            if not flag:
                return False
            queue.append(node.right)
        else:
            flag = False
    return True

def isCompleteBT(root):
    return is_complete_binary_tree(root)
